import express from "express";
import { z } from "zod";

const app = express();
app.use(express.json());

const validate = (schemas) => (req, res, next) => {
  req.valid = {};
  for (const [part, schema] of Object.entries(schemas)) {
    const result = schema.safeParse(req[part] ?? {});
    if (!result.success) {
      return res.status(400).json({ error: "validation failed", part, issues: z.flattenError(result.error).fieldErrors });
    }
    req.valid[part] = result.data;
  }
  next();
};

const createUser = z.object({
  email: z.email(),
  name: z.string().trim().min(1).max(100),
  age: z.number().int().min(13).optional(),
});                                       // unknown keys (e.g. "role") are stripped
const listQuery = z.object({ page: z.coerce.number().int().min(1).default(1) });

app.post("/users", validate({ body: createUser }), (req, res) => res.status(201).json(req.valid.body));
app.get("/users", validate({ query: listQuery }), (req, res) => res.json({ page: req.valid.query.page }));

app.listen(3000);

import express from "express";
const app = express();
app.use(express.json());

const articles = new Map();
let nextId = 1;

app.get("/v1/articles", (req, res) => {
  const limit = Math.min(Number(req.query.limit) || 20, 100);     // cap page size
  const after = Number(req.query.cursor) || 0;
  const page = [...articles.values()].filter((a) => a.id > after).slice(0, limit);
  res.json({ data: page, nextCursor: page.length === limit ? page.at(-1).id : null });
});

app.post("/v1/articles", (req, res) => {
  const article = { id: nextId++, title: String(req.body?.title ?? "untitled") };
  articles.set(article.id, article);
  res.status(201).location(`/v1/articles/${article.id}`).json(article);
});

app.patch("/v1/articles/:id", (req, res) => {
  const article = articles.get(Number(req.params.id));
  if (!article) return res.status(404).json({ error: { code: "not_found", message: "Article not found" } });
  if (typeof req.body?.title === "string") article.title = req.body.title;
  res.json(article);
});

app.delete("/v1/articles/:id", (req, res) => { articles.delete(Number(req.params.id)); res.status(204).end(); });
app.listen(3000);

