const app = express();

const allowed = new Set(["https://app.example.com", "http://localhost:5173"]);

app.use(cors({
  origin(origin, callback) {
    // Non-browser clients send no Origin header; allow them (CORS doesn't apply)
    if (!origin || allowed.has(origin)) return callback(null, true);
    callback(null, false);                    // no CORS headers -> browser blocks the read
  },
  credentials: true,                          // allow cookies; requires a specific origin
  methods: ["GET", "POST", "PATCH", "DELETE"],
  allowedHeaders: ["Content-Type", "Authorization"],
  maxAge: 600,                                // cache preflight for 10 minutes
}));

