import express from "express";
import jwt from "jsonwebtoken";
import { scrypt, randomBytes, timingSafeEqual } from "node:crypto";
import { promisify } from "node:util";

const scryptAsync = promisify(scrypt);
const SECRET = process.env.JWT_SECRET ?? "dev-only-secret";
const hash = async (pw, salt = randomBytes(16)) => ({ salt, key: await scryptAsync(pw, salt, 64) });
const users = new Map([["ada@example.com", { id: "u1", ...(await hash("correct horse")) }]]);

const app = express();
app.use(express.json());

app.post("/login", async (req, res) => {
  const user = users.get(req.body?.email);
  const key = user && (await scryptAsync(String(req.body.password), user.salt, 64));
  if (!user || !timingSafeEqual(key, user.key)) return res.status(401).json({ error: "invalid credentials" });
  res.json({ token: jwt.sign({ sub: user.id }, SECRET, { expiresIn: "15m" }) });
});

function requireAuth(req, res, next) {
  const token = req.get("authorization")?.replace(/^Bearer /, "");
  try { req.user = jwt.verify(token, SECRET, { algorithms: ["HS256"] }); next(); }
  catch { res.status(401).json({ error: "unauthenticated" }); }
}

app.get("/me", requireAuth, (req, res) => res.json({ userId: req.user.sub }));
app.listen(3000);

