// Tiny TTL cache for an expensive, shared computation
const cache = new Map();
async function cached(key, ttlMs, compute) {
  const hit = cache.get(key);
  if (hit && hit.expires > Date.now()) return hit.value;
  const value = await compute();
  cache.set(key, { value, expires: Date.now() + ttlMs });
  return value;
}

app.get("/api/leaderboard", async (req, res) => {
  const board = await cached("leaderboard", 30_000, async () => {
    await new Promise((r) => setTimeout(r, 200));       // pretend: slow aggregate query
    return [{ user: "ada", score: 99 }];
  });
  res.set("Cache-Control", "public, max-age=30");       // browsers/CDNs may reuse for 30 s
  res.json(board);                                      // weak ETag -> 304 on If-None-Match
});

