// tenant.js — publishable middleware factory
export function tenantResolver({ header = "x-tenant-id", lookup, required = true } = {}) {
  if (typeof lookup !== "function") throw new TypeError("tenantResolver: lookup(id) is required");

  return async function tenantResolverMiddleware(req, res, next) {   // named for stack traces
    try {
      const id = req.get(header);
      if (!id) {
        if (!required) return next();
        return next(Object.assign(new Error(`missing ${header} header`), { status: 400 }));
      }
      const tenant = await lookup(id);
      if (!tenant) return next(Object.assign(new Error("unknown tenant"), { status: 404 }));
      res.locals.tenant = tenant;                // per-request, no shared state
      next();
    } catch (err) {
      next(err);                                 // also correct under Express 4
    }
  };
}

